using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using Frociart;
internal static class PauseImportTests {
 static int checks;static void Check(bool yes,string why){if(!yes)throw new Exception(why);checks++;}static string Text(string s){return(string)ExpressionLanguage.Evaluate(s,null);}static string Normal(string s){return s.Replace("\r\n","\n");}
 static IEnumerable<FlowNode> Nodes(Diagram d){return d.Nodes.Concat(d.Functions==null?Enumerable.Empty<FlowNode>():d.Functions.SelectMany(f=>f.Body.Nodes));}
 static void Run(Diagram d,string[] row,bool ignore=false){string encoded=Convert.ToBase64String(DiagramIO.EncodeDocument(d));var r=new Interpreter(d);var debug=new FlowDebugger(r,d){IgnoreBreakpoints=ignore};var hits=new List<string>();debug.Begin(FlowDebugger.Command.Continue);for(int i=0;i<3000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++){int steps=r.Steps;string id=r.CurrentNodeId;debug.Tick();if(!debug.Active&&debug.AtBreakpoint){Check(r.Steps==steps&&r.CurrentNodeId==id,"Pause is before execution");object x;hits.Add(r.Variables.TryGetValue("x",out x)?ValueFormatter.Format(x):"_");Check(debug.Begin(FlowDebugger.Command.Continue),"Resume accepted");}}Check(r.State==RuntimeState.Completed,"Completes "+row[0]+": "+r.Error);Check(Normal(r.OutputText)==Text(row[1]),"Output unchanged "+row[0]);Check(String.Join("|",hits)==(ignore?"":row[2]),"Exact pause order "+row[0]+": "+String.Join("|",hits));Check(Convert.ToBase64String(DiagramIO.EncodeDocument(d))==encoded,"Debug execution never changes graph");}
 [STAThread]static int Main(string[] args){try{string root=args[0];Directory.CreateDirectory(Path.Combine(root,"pc"));foreach(string line in File.ReadAllLines(Path.Combine(root,"cases.tsv"),Encoding.UTF8)){var row=line.Split('\t');string path=Path.Combine(root,"fixtures",row[0]+".fprg");byte[] before=File.ReadAllBytes(path);var d=DiagramIO.Load(path);var pauses=Nodes(d).Where(n=>n.Kind==NodeKind.Pause).ToArray();Check(pauses.Length>0&&pauses.All(n=>n.Text=="Pausa"&&n.Breakpoint),"Dedicated pause nodes, no fake assignments");Check(!Encoding.UTF8.GetString(DiagramIO.EncodeDocument(d)).Contains("PRIVATE_"),"Metadata removed");Run(d,row);Run(d,row,true);Run(DiagramIO.Clone(d),row);var pseudo=FlowPseudocode.Decode(FlowPseudocode.Encode(d));Check(Nodes(pseudo).Count(n=>n.Kind==NodeKind.Pause)==pauses.Length,"Pseudocode keeps every pause");Run(pseudo,row);string save=Path.Combine(root,"pc",row[0]+".frociart");DiagramIO.Save(save,d);Run(DiagramIO.Load(save),row);Run(FlowClipboard.Decode(FlowClipboard.Encode(d)),row);FlowLayout.Arrange(d);Run(d,row);Check(before.SequenceEqual(File.ReadAllBytes(path)),"Source file untouched");string generated=Path.Combine(root,"generated-pc");Directory.CreateDirectory(generated);var program=FlowSource.Compile(d);string className="Pc"+Array.IndexOf(File.ReadAllLines(Path.Combine(root,"cases.tsv"),Encoding.UTF8),line);using(var stream=typeof(Diagram).Assembly.GetManifestResourceStream("Frociart.Source.JavaRuntime.txt"))using(var reader=new StreamReader(stream)){File.WriteAllText(Path.Combine(generated,className+".java"),FlowJava.Generate(program,reader.ReadToEnd(),className).Text,new UTF8Encoding(false));}File.WriteAllText(Path.Combine(generated,row[0]+".py"),FlowPython.Generate(program).Text,new UTF8Encoding(false));Check(true,"Both source exporters handle pause");}
 foreach(string file in Directory.GetFiles(Path.Combine(root,"fixtures"),"reject-*.fprg")){bool rejected=false;try{DiagramIO.Load(file);}catch(InvalidDataException e){rejected=e.Message.Contains("Flowgorithm");}Check(rejected,"Atomic reject "+Path.GetFileName(file));}
 foreach(string code in new[]{"PAUSA","PAUSA SE x >= 3","PAUSA_DISATTIVATA","PAUSA_DISATTIVATA SE x >= 3","PAUSA_DISATTIVATA SE x >"}){var d=FlowPseudocode.Decode("x = 3\n"+code+"\nSTAMPA x");var row=new[]{code,"\"3\"",code.StartsWith("PAUSA_DISATTIVATA")?"":"3"};Run(d,row);Run(FlowPseudocode.Decode(FlowPseudocode.Encode(d)),row);}
 var error=FlowPseudocode.Decode("x = 5\nPAUSA SE 42\nSTAMPA x");var runner=new Interpreter(error);var control=new FlowDebugger(runner,error);control.Begin(FlowDebugger.Command.Continue);for(int i=0;i<20&&control.Active;i++)control.Tick();Check(control.AtBreakpoint&&control.Message.Contains("vero o falso")&&runner.Output.Count==0,"Bad condition type pauses with visible error and no output");control.Begin(FlowDebugger.Command.Continue);for(int i=0;i<20&&control.Active;i++)control.Tick();Check(runner.State==RuntimeState.Completed&&runner.OutputText=="5","Resume recovers from condition error without relocation");
 Console.WriteLine("PAUSE_IMPORT_PC PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
